// CommonJS — 실행해 봐야 안다
if (isDev) { const debug = require('./debug'); }   // 조건부 가능

// ESM — 실행 전에 알 수 있다
import debug from './debug';        // 항상 맨 위, 항상 실행
const debug = await import('./debug');   // 동적 import 는 따로 있다 (4장)

// vite.config.js
import { defineConfig } from 'vite';
export default defineConfig({
  build: {
    target: 'es2022',          // 어느 문법까지 그대로 둘까 (7장)
    sourcemap: true,           // 배포 디버깅에 필요 (cs-compiler 8장)
  },
});

// 요즘 도구들은 「설정 없이 시작」을 지향한다 —
// 설정이 길어진다면 대개 특수한 요구가 있다는 뜻

// ① 라우트 — 가장 기본
const Admin = lazy(() => import('./routes/Admin'));

// ② 무거운 라이브러리를 쓰는 순간까지
async function exportPdf() {
  const { jsPDF } = await import('jspdf');   // 누를 때 받는다
  …
}

// ③ 조건부 기능 (관리자·실험 기능)
if (user.isAdmin) { const m = await import('./admin-tools'); m.init(); }

{
  "name": "my-lib",
  "type": "module",
  "sideEffects": false,          // 이 패키지는 부수효과가 없다 → 마음껏 지워도 된다
  "exports": {
    ".": "./dist/index.js",
    "./button": "./dist/button.js"   // 개별 경로로 가져갈 수 있게
  }
}

// CSS 처럼 부수효과가 있는 파일만 예외로 표시
// "sideEffects": ["*.css"]

// 오래된 브라우저를 받치면 문법이 옛것으로 변환되어 코드가 커진다
build: { target: 'es2015' }    // 크고 안전
build: { target: 'es2022' }    // 작고 빠름 (요즘 브라우저 대상)

// browserslist 로 한 곳에서 관리
// package.json
"browserslist": ["> 0.5%", "last 2 versions", "not dead"]

// 실제 사용자 통계를 보고 정하라 — 「혹시 몰라서」 옛 브라우저를 받치면 모두가 비용을 낸다
